create table if not exists private.quality_probe_config (singleton boolean primary key default true check(singleton),enabled boolean not null default true,target_base_url text not null,token_hash text not null,updated_at timestamptz not null default now());
create table if not exists private.quality_synthetic_probes (id bigserial primary key,probe_key text not null unique,status text not null check(status in ('healthy','degraded','failed')),results jsonb not null default '{}'::jsonb,duration_ms integer,created_at timestamptz not null default now());
create index if not exists quality_synthetic_probes_created_idx on private.quality_synthetic_probes(created_at desc);
do $$ declare v_token text; begin select decrypted_secret into v_token from vault.decrypted_secrets where name='quality_runtime_probe_token' order by created_at desc limit 1; if v_token is null then v_token:=encode(gen_random_bytes(32),'hex'); perform vault.create_secret(v_token,'quality_runtime_probe_token','World_server synthetic quality probe token'); end if; insert into private.quality_probe_config(singleton,enabled,target_base_url,token_hash,updated_at) values(true,true,'https://world-server.vercel.app',encode(digest(v_token,'sha256'),'hex'),now()) on conflict(singleton) do update set enabled=true,target_base_url=excluded.target_base_url,token_hash=excluded.token_hash,updated_at=now(); end $$;
create or replace function public.quality_verify_probe_token(p_token text) returns boolean language sql security definer set search_path='private','extensions','pg_temp' as $$ select exists(select 1 from private.quality_probe_config where singleton=true and enabled=true and token_hash=encode(digest(coalesce(p_token,''),'sha256'),'hex')); $$;
create or replace function public.quality_record_synthetic_probe(p_result jsonb) returns jsonb language plpgsql security definer set search_path='private','public','pg_temp' as $$ declare v_key text:=nullif(trim(p_result->>'probeKey'),''); v_status text:=coalesce(nullif(trim(p_result->>'status'),''),'failed'); v_id bigint; v_duration integer:=coalesce((p_result->>'durationMs')::integer,0); begin if v_key is null then raise exception 'probeKey required'; end if; if v_status not in ('healthy','degraded','failed') then v_status:='failed'; end if; insert into private.quality_synthetic_probes(probe_key,status,results,duration_ms) values(left(v_key,180),v_status,coalesce(p_result,'{}'::jsonb),greatest(0,least(v_duration,120000))) on conflict(probe_key) do update set status=excluded.status,results=excluded.results,duration_ms=excluded.duration_ms,created_at=now() returning id into v_id; perform public.quality_record_provider_health('vercel',v_status='healthy','synthetic-probe',coalesce(p_result,'{}'::jsonb)); return jsonb_build_object('id',v_id,'probeKey',v_key,'status',v_status,'recordedAt',now()); end $$;
create or replace function public.quality_latest_synthetic_probe() returns jsonb language sql security definer set search_path='private','pg_temp' as $$ select coalesce((select jsonb_build_object('probeKey',probe_key,'status',status,'durationMs',duration_ms,'createdAt',created_at,'results',results) from private.quality_synthetic_probes order by created_at desc limit 1),'{}'::jsonb); $$;
create or replace function public.quality_runtime_housekeeping() returns jsonb language plpgsql security definer set search_path='private','public','pg_temp' as $$ declare v_probe bigint:=0; v_jobs bigint:=0; v_web bigint:=0; v_samples bigint:=0; v_runs bigint:=0; begin delete from private.quality_synthetic_probes where created_at<now()-interval '14 days'; get diagnostics v_probe=row_count; delete from public.quality_worker_jobs where status in ('complete','failed','cancelled') and updated_at<now()-interval '30 days'; get diagnostics v_jobs=row_count; delete from public.quality_telemetry where created_at<now()-interval '30 days'; get diagnostics v_web=row_count; delete from public.quality_telemetry_samples where created_at<now()-interval '30 days'; get diagnostics v_samples=row_count; delete from private.quality_autopilot_runs where created_at<now()-interval '90 days'; get diagnostics v_runs=row_count; return jsonb_build_object('probesDeleted',v_probe,'jobsDeleted',v_jobs,'webTelemetryDeleted',v_web,'samplesDeleted',v_samples,'runsDeleted',v_runs,'at',now()); end $$;
create or replace function public.quality_export_migration_history() returns jsonb language sql security definer set search_path='supabase_migrations','extensions','pg_temp' as $$ select jsonb_build_object('count',count(*),'digest',encode(digest(coalesce(string_agg(version || '_' || name || '.sql', E'\n' order by version),''),'sha256'),'hex'),'latest',(array_agg(version || '_' || name || '.sql' order by version desc))[1],'migrations',coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name,'statements',to_jsonb(statements),'rollback',to_jsonb(rollback)) order by version),'[]'::jsonb)) from supabase_migrations.schema_migrations; $$;
create or replace function public.quality_migration_history_digest() returns jsonb language sql security definer set search_path='supabase_migrations','extensions','pg_temp' as $$ select jsonb_build_object('count',count(*),'digest',encode(digest(coalesce(string_agg(version || '_' || name || '.sql', E'\n' order by version),''),'sha256'),'hex'),'latest',(array_agg(version || '_' || name || '.sql' order by version desc))[1]) from supabase_migrations.schema_migrations; $$;
revoke all on function public.quality_verify_probe_token(text) from public,anon,authenticated; revoke all on function public.quality_record_synthetic_probe(jsonb) from public,anon,authenticated; revoke all on function public.quality_latest_synthetic_probe() from public,anon,authenticated; revoke all on function public.quality_runtime_housekeeping() from public,anon,authenticated; revoke all on function public.quality_export_migration_history() from public,anon,authenticated; revoke all on function public.quality_migration_history_digest() from public,anon,authenticated;
grant execute on function public.quality_verify_probe_token(text) to service_role; grant execute on function public.quality_record_synthetic_probe(jsonb) to service_role; grant execute on function public.quality_latest_synthetic_probe() to service_role; grant execute on function public.quality_runtime_housekeeping() to service_role; grant execute on function public.quality_export_migration_history() to service_role; grant execute on function public.quality_migration_history_digest() to service_role;
select cron.unschedule(jobid) from cron.job where jobname in ('quality-synthetic-probe-v10','quality-runtime-housekeeping-v10');
select cron.schedule('quality-synthetic-probe-v10','*/5 * * * *',$cron$ select net.http_post(url:='https://iphfwxjuhsucvdyluink.supabase.co/functions/v1/quality-runtime-probe',body:='{}'::jsonb,headers:=jsonb_build_object('Content-Type','application/json','x-quality-cron-token',(select decrypted_secret from vault.decrypted_secrets where name='quality_runtime_probe_token' order by created_at desc limit 1)),timeout_milliseconds:=15000); $cron$);
select cron.schedule('quality-runtime-housekeeping-v10','37 3 * * *','select public.quality_runtime_housekeeping();');
